// node bench.mjs <send|recv> <seed> '<cfg json>'
// Raw relay-only WebRTC transfer of cfg.bytes generated bytes, striped over cfg.pcs connections
// with cfg.channels ordered channels each. The receiver sends nothing once the channels are open.
// cfg: { bytes, pcs, channels, chunk: bytes | 'max', high, low, transport }
import http from 'node:http';
import crypto from 'node:crypto';
import { SITE, launch, iceServers } from './common.mjs';
import { snap, diff } from './procs.mjs';

const [role, seed, raw] = process.argv.slice(2);
const cfg = { pcs: 1, channels: 1, chunk: 262144, high: 4 << 20, low: 1 << 20, transport: 'app', ...JSON.parse(raw) };
const h = (s) => crypto.createHash('sha256').update(s).digest('hex');
const room = (i) => h(`${seed}|${i}`).slice(0, 32);
const rid = h(`${seed}|r`).slice(0, 16);
const me = role === 'send' ? 's' : rid, peer = role === 'send' ? rid : 's';

async function post(i, data) {
  const r = await fetch(`${SITE}/api/signal`, { method: 'POST', body: JSON.stringify({ room: room(i), from: me, to: peer, data }) });
  if (r.status !== 204) throw new Error(`signal POST ${r.status}`);
}
async function take(i, t) {
  for (const end = Date.now() + 90_000; Date.now() < end;) {
    const r = await fetch(`${SITE}/api/signal?room=${room(i)}&me=${me}`);
    if (!r.ok) throw new Error(`signal GET ${r.status}`);
    const m = (await r.json()).find((e) => e.data?.t === t);
    if (m) return m.data.sdp;
  }
  throw new Error(`no ${t} for pc ${i}`);
}

const server = http.createServer((q, s) => s.end('<!doctype html><title>bench</title>')).listen(0, '127.0.0.1');
await new Promise((ok) => server.once('listening', ok));
const browser = await launch();
const marks = {};
let result;
try {
  const page = await browser.newPage();
  await page.exposeFunction('post', post);
  await page.exposeFunction('take', take);
  await page.exposeFunction('mark', (name) => { marks[name] = snap(); });
  await page.goto(`http://127.0.0.1:${server.address().port}/`);
  // creds 'each': connection i uses this sandbox's credential cred + i, so each is a separate TURN user
  const ice = Array.from({ length: cfg.pcs }, (_, i) => iceServers(cfg.transport, ((cfg.cred ?? 0) + (cfg.creds === 'each' ? i : 0)) % 4));
  result = await page.evaluate(run, { role, cfg, ice });
  result.cpu = marks.start && marks.end ? diff(marks.start, marks.end) : null;
  result.chrome = await browser.version();
} catch (err) {
  result = { error: String(err?.stack || err) };
} finally {
  await browser.close();
  server.close();
}
console.log('RESULT ' + JSON.stringify({ role, cfg, ...result }));

// ---- runs in the page ----
async function run({ role, cfg, ice }) {
  const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
  const gathered = (pc) => new Promise((ok) => {
    const check = () => pc.iceGatheringState === 'complete' && ok();
    pc.addEventListener('icegatheringstatechange', check);
    setTimeout(ok, 8000);
    check();
  });
  const relayOnly = (sdp) => {
    const bad = sdp.split('\r\n').filter((l) => l.startsWith('a=candidate:') && l.split(' ')[7] !== 'relay');
    if (bad.length) throw new Error(`non-relay candidate: ${bad[0]}`);
    return sdp;
  };
  const switches = [];
  const pcs = Array.from({ length: cfg.pcs }, (_, i) => new RTCPeerConnection({ iceTransportPolicy: 'relay', iceServers: ice[i] }));
  const lanes = [];
  const t0 = performance.now();
  pcs.forEach((pc, i) => pc.addEventListener('connectionstatechange', () => {
    const ice = pc.sctp?.transport?.iceTransport;
    if (ice && !ice.__watched) {
      ice.__watched = true;
      ice.addEventListener('selectedcandidatepairchange', () => {
        const p = ice.getSelectedCandidatePair();
        switches.push({ pc: i, ms: Math.round(performance.now() - t0), local: `${p.local.protocol}:${p.local.port}`, remote: `${p.remote.address}:${p.remote.port}` });
      });
    }
  }));

  if (role === 'send') {
    const opened = [];
    pcs.forEach((pc) => {
      for (let j = 0; j < cfg.channels; j++) {
        const dc = pc.createDataChannel(`f${j}`);
        dc.binaryType = 'arraybuffer';
        dc.bufferedAmountLowThreshold = cfg.low;
        lanes.push({ dc, pc });
        opened.push(new Promise((ok, fail) => { dc.onopen = ok; dc.onclose = () => fail(new Error('closed before open')); }));
      }
    });
    await Promise.all(pcs.map(async (pc, i) => {
      await pc.setLocalDescription();
      await gathered(pc);
      await post(i, { t: 'offer', sdp: { type: 'offer', sdp: relayOnly(pc.localDescription.sdp) } });
      await pc.setRemoteDescription(await take(i, 'answer'));
    }));
    await Promise.all(opened);
    const connectMs = performance.now() - t0;
    await sleep(500);
    const max = pcs[0].sctp.maxMessageSize;
    const chunk = Math.min(cfg.chunk === 'max' ? max : cfg.chunk, max);
    const BLOCK = 8 << 20;
    const buf = new Uint8Array(BLOCK);
    crypto.getRandomValues(buf.subarray(0, 65536));
    for (let i = 65536; i < BLOCK; i += 65536) buf.copyWithin(i, 0, 65536);
    const share = Math.ceil(cfg.bytes / lanes.length);
    let stalls = 0;
    await mark('start');
    const ts = performance.now();
    const pumps = Promise.all(lanes.map(async ({ dc }, k) => {
      const n = Math.min(share, cfg.bytes - k * share);
      let sent = 0, m = 0;
      while (sent < n) {
        if (dc.bufferedAmount > cfg.high) {
          stalls++;
          await new Promise((ok, fail) => {
            dc.onbufferedamountlow = () => { dc.onbufferedamountlow = null; ok(); };
            dc.onclose = () => fail(new Error('closed mid-transfer'));
          });
        }
        const off = sent % BLOCK, len = Math.min(chunk, n - sent, BLOCK - off);
        buf[off] = m & 255;
        dc.send(buf.subarray(off, off + len));
        sent += len;
        m++;
      }
      dc.send(JSON.stringify({ t: 'done', bytes: n, msgs: m }));
      while (dc.bufferedAmount > 0) await sleep(20);
    }));
    const timedOut = await Promise.race([pumps.then(() => false), sleep(100_000).then(() => true)]);
    const sendSecs = (performance.now() - ts) / 1000;
    await mark('end');
    const pairs = await Promise.all(pcs.map(pairOf));
    await sleep(3000); // let the receiver read its stats before the connections close
    pcs.forEach((pc) => pc.close());
    return { connectMs, chunk, maxMessageSize: max, sendSecs, stalls, pairs, switches, timedOut };
  }

  const done = new Promise((finish, fail) => {
    let first = 0, ended = 0, got = 0, bad = 0, warm = null, timeline = []; // warm: [ms, bytes] once 1 s has passed
    const want = cfg.pcs * cfg.channels;
    let last = 0;
    const tick = setInterval(() => first && (timeline.push(+((got - last) / 0.5e6).toFixed(1)), (last = got)), 500);
    pcs.forEach((pc) => {
      pc.ondatachannel = ({ channel: dc }) => {
        dc.binaryType = 'arraybuffer';
        const lane = { bytes: 0, msgs: 0 };
        lanes.push(lane);
        dc.onmessage = ({ data }) => {
          if (typeof data === 'string') {
            const m = JSON.parse(data);
            if (m.bytes !== lane.bytes || m.msgs !== lane.msgs) bad++;
            if (++ended === want) {
              const now = performance.now();
              clearInterval(tick);
              finish({ secs: (now - first) / 1000, got, bad, lanes, timeline, switches, steadyMBps: warm ? (got - warm[1]) / 1e3 / (now - warm[0]) : null });
            }
            return;
          }
          if (!first) { first = performance.now(); mark('start'); }
          else if (!warm && performance.now() - first >= 1000) warm = [performance.now(), got];
          if (new Uint8Array(data, 0, 1)[0] !== (lane.msgs & 255)) bad++;
          lane.bytes += data.byteLength;
          lane.msgs++;
          got += data.byteLength;
        };
        dc.onclose = () => ended < want && fail(new Error('channel closed early'));
        setTimeout(() => ended < want && (clearInterval(tick), finish({ timeout: true, secs: (performance.now() - first) / 1000, got, bad, lanes, timeline, switches })), 100_000 + 30_000);
      };
    });
  });
  await Promise.all(pcs.map(async (pc, i) => {
    await pc.setRemoteDescription(await take(i, 'offer'));
    await pc.setLocalDescription();
    await gathered(pc);
    await post(i, { t: 'answer', sdp: { type: 'answer', sdp: relayOnly(pc.localDescription.sdp) } });
  }));
  const r = await Promise.race([done, sleep(100_000).then(() => { throw new Error('timeout'); })]);
  await mark('end');
  const pairs = await Promise.all(pcs.map(pairOf));
  pcs.forEach((pc) => pc.close());
  return { ...r, MBps: r.got / 1e6 / r.secs, ok: r.got === cfg.bytes && r.bad === 0, pairs };

  async function pairOf(pc) {
    const stats = await pc.getStats();
    let pair;
    stats.forEach((s) => s.type === 'transport' && (pair = stats.get(s.selectedCandidatePairId)));
    if (!pair) return null;
    const l = stats.get(pair.localCandidateId), rm = stats.get(pair.remoteCandidateId);
    return {
      local: `${l.candidateType}/${l.protocol}/${l.relayProtocol ?? '-'}/${l.url ?? ''}`,
      remote: `${rm.candidateType}/${rm.protocol}`,
      rttMs: pair.currentRoundTripTime * 1000,
      sent: pair.bytesSent, received: pair.bytesReceived,
    };
  }
}
